 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background] * w for _ in range(h)]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] == color and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            # One-cell components are stray marks; larger components are
            # rectangular objects with stray pixels occluding some cells.
            if len(cells) >= 2:
                objects.append((color, min(y for y, x in cells),
                                max(y for y, x in cells), min(x for y, x in cells),
                                max(x for y, x in cells)))
    for color, r0, r1, c0, c1 in objects:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out


